2|// recomputed here from the payload's edges and per-path means; the daily series come from the server's reweight.
3|(() => {
4|  "use strict";
5|  const $ = (id) => document.getElementById(id);
6|  let D = JSON.parse($("page-data").textContent);
7|  const API = document.querySelector(".app").dataset.api;
8|  const S = { view: "lit", mtab: "exposure", rtab: "probs", tile: null, overrides: {}, sel: {},
9|              omode: "weighted", detail: null, event: D.event, bank: D.bank, settings: {}, lat: [],
10|              reveal: false, outcome: null };
11|  window.__page = S;
12|  const CLS_COL = ["#b91c1c", "#dc2626", "#f87171", "#15803d", "#22c55e", "#2563eb", "#9ca3af", "#a16207"];
13|  const NEUTRAL = D.meta.judgments === "neutral";
14|
15|  // --- formatting ---------------------------------------------------------------------------------------------
16|  const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
17|  const money = (c, dp) => {
18|    const v = c / 100, a = Math.abs(v), s = v < 0 ? "−" : "";
19|    if (a >= 1e6) return `${s}$${(a / 1e6).toFixed(dp ?? 2)}M`;
20|    if (a >= 1e3) return `${s}$${(a / 1e3).toFixed(dp ?? 0)}k`;
21|    return `${s}$${a.toFixed(0)}`;
22|  };
23|  const MON = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
24|  const pct = (p, dp = 1) => `${(100 * p).toFixed(dp)}%`;
25|  const pts = (x) => `${(100 * x).toFixed(1)} pts`;
26|  const ACT = "#047857";  // the actual-outcome reveal's colour
27|  const fdate = (iso) => new Date(iso + "T12:00:00").toLocaleDateString("en-GB", { day: "numeric", month: "short" });
28|  const fdateY = (iso) => new Date(iso + "T12:00:00").toLocaleDateString("en-GB", { day: "numeric", month: "short", year: "numeric" });
29|
30|  // --- probability arithmetic ---------------------------------------------------------------------------------
31|  const N = D.nodes.length, P = D.paths.edges.length;
32|  const jevDist = (i) => D.nodes[i].jev;
33|  const dist = (i, ov = S.overrides) => ov[D.nodes[i].key] || jevDist(i);
34|  const neutralDist = (i) => D.nodes[i].branches.map(() => 1 / D.nodes[i].branches.length);
35|  function pathProbs(get) {
36|    const node = []; for (let i = 0; i < N; i++) node.push(get(i));
37|    const comp = D.composites.map((conj) => {
38|      let y = 0;
39|      for (const c of conj) { let p = 1; for (const [n, b] of c) p *= node[n][b]; y += p; }
40|      y = Math.min(Math.max(y, 0), 1); return [y, 1 - y];
41|    });
42|    const out = new Float64Array(P);
43|    for (let i = 0; i < P; i++) {
44|      const e = D.paths.edges[i]; let p = 1;
45|      for (let j = 0; j < e.length; j += 2) p *= e[j] >= 0 ? node[e[j]][e[j + 1]] : comp[-e[j] - 1][e[j + 1]];
46|      out[i] = p;
47|    }
48|    return out;
49|  }
50|  const expect = (probs, key) => { const x = D.paths.scalars[key]; let s = 0; for (let i = 0; i < P; i++) s += probs[i] * x[i]; return s; };
51|  // The bank view: its own paths over the bank rows (asked on bank data alone), reweighted the same way.
52|  const BE = D.bank.edges || [];
53|  const bankProbs = (get) => BE.map((e) => { let p = 1; for (let j = 0; j < e.length; j += 2) p *= get(e[j])[e[j + 1]]; return p; });
54|  const bexpect = (bp, key) => {
55|    const x = (D.bank.path_scalars || {})[key]; if (!x) return D.bank.scalars[key];
56|    let s = 0; for (let i = 0; i < bp.length; i++) s += bp[i] * x[i]; return s;
57|  };
58|  // A slider sets the selected branch; the other branches keep their proportions in `base`, the distribution when
59|  // the drag started (uniform if they were all zero), so the result depends only on where the slider ends up.
60|  function withBranch(i, b, x, base = dist(i)) {
61|    const rest = base.reduce((s, v, k) => s + (k === b ? 0 : v), 0), n = base.length;
62|    return base.map((v, k) => (k === b ? x : rest > 0 ? (1 - x) * v / rest : (1 - x) / (n - 1)));
63|  }
64|
65|  // --- tiles: the lender bridge, funded -> payments due -> collected -----------------------------------------------
66|  const END = fdate(D.meta.horizon);
67|  // good: +1 if more helps the lender, -1 if more hurts it, 0 for volume (coloured neither way)
68|  const TILES = [
69|    { key: "funded", label: "Funded", fmt: money, good: 0, tab: "collections", hl: ["drawn"] },
70|    { key: "due", label: `Payments due by ${END}`, fmt: money, good: 0, tab: "collections", hl: ["due"] },
71|    { key: "collected", label: "Collected", fmt: money, good: +1, tab: "collections", hl: ["collected"] },
72|    { key: "unpaid", label: "Due and unpaid", fmt: money, good: -1, tab: "collections", hl: ["past_due", "frozen_due"] },
73|    { key: "petition_p", label: `Chance of a filing by ${END}`, fmt: (p) => pct(p), good: -1, tab: "exposure", hl: ["petition"] },
74|    { key: "clawback", label: "Clawback exposure (gross, before new value)", fmt: money, good: -1, tab: "collections", hl: ["clawback"],
75|      tip: "Collections in the 90 days before a filing" },
76|  ];
77|  let probs = pathProbs((i) => dist(i));
78|  let steps = null;  // [bank, + research at even odds, + Jev] per scalar key
79|  function attribution() {
80|    const neu = pathProbs(neutralDist), bp = bankProbs((i) => dist(i));
81|    steps = {};
82|    for (const k of Object.keys(D.paths.scalars)) steps[k] = [bexpect(bp, k), expect(neu, k), expect(probs, k)];
83|  }
84|  // What research adds, signed and coloured by whether it helps (green) or hurts (red) the lender.
85|  function adds(d, good, fmt) {
86|    const cls = Math.abs(d) < 1e-9 || !good ? "" : (d > 0) === (good > 0) ? "down" : "up";
87|    return `<span class="d ${cls}">${d >= 0 ? "+" : "−"}${fmt(Math.abs(d))}</span>`;
88|  }
89|  const dollars = (c) => `$${Math.round(Math.abs(c) / 100).toLocaleString("en-US")}`;
90|  // The change in collections in its two parts: payments due (Slope funds more or less, so more or fewer
91|  // installments fall due) and due and unpaid. In whole dollars, the second part taken as the rest, so the line adds up.
92|  function bridgeLine() {
