97|      + `${amt(dDue, "br-due")} from ${dDue <= 0 ? "fewer installments due, because Slope funds less" : "more installments due, because Slope funds more"}, and `
98|      + `${amt(dUn, "br-unpaid")} from ${dUn <= 0 ? "more due but unpaid" : "less due but unpaid"}.`;
